import copy
import importlib
import os
import random
import unittest

from linemeter import BudgetExceeded, LineMeter
from batchcalc.compute import package_mixes


def oracle(a, b):
    table = [0] * (a + 1)
    table[0] = 1
    for c in b:
        for v in range(c, a + 1):
            table[v] += table[v - c]
    return table[a]


def small_args(rng):
    coins = sorted(rng.sample(range(1, 10), rng.randint(0, 4)))
    return (rng.randint(0, 30), coins)


def big_args(rng, n):
    coins = sorted({1} | set(rng.sample([2, 3, 5, 10, 20, 25, 50], rng.randint(4, 6))))
    return (n, coins)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(2000)
        for _ in range(150):
            args = small_args(rng)
            self.assertEqual(package_mixes(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_inputs_are_not_modified(self):
        rng = random.Random(2001)
        for _ in range(40):
            args = small_args(rng)
            before = copy.deepcopy(args)
            package_mixes(*args)
            self.assertEqual(args, before)

