def package_mixes(units, sizes):
    """Number of different mixes of package sizes that add up to the ordered units."""
    ways = [1] + [0] * units
    for coin in sizes:
        for value in range(coin, units + 1):
            ways[value] += ways[value - coin]
    return ways[units]


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

