def package_mixes(units, sizes):
    """Number of different mixes of package sizes that add up to the ordered units."""

    def go(i, left):
        if left == 0:
            return 1
        if i == len(sizes) or left < 0:
            return 0
        return go(i, left - sizes[i]) + go(i + 1, left)

    return go(0, units)


