"""gridwork: calculations used by the nightly batch jobs."""


def palindrome_cuts(word):
    """Minimum number of cuts so every piece is a palindrome."""
    size = len(word)
    pal = [[False] * size for _ in range(size)]
    for i in range(size - 1, -1, -1):
        for j in range(i, size):
            if word[i] == word[j] and (j - i < 2 or pal[i + 1][j - 1]):
                pal[i][j] = True
    cuts = [0] * size
    for j in range(size):
        if pal[0][j]:
            cuts[j] = 0
        else:
            cuts[j] = min(cuts[i - 1] + 1 for i in range(1, j + 1) if pal[i][j])
    return cuts[-1] if size else -1


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

