"""gridwork: calculations used by the nightly batch jobs."""


def palindrome_cuts(word):
    """Minimum number of cuts so every piece is a palindrome."""

    def is_pal(i, j):
        while i < j:
            if word[i] != word[j]:
                return False
            i += 1
            j -= 1
        return True

    def best(i):
        if i == len(word):
            return -1
        result = len(word)
        for j in range(i, len(word)):
            if is_pal(i, j):
                result = min(result, 1 + best(j + 1))
        return result

    return best(0)


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

