import copy
import importlib
import os
import random
import unittest

from linemeter import BudgetExceeded, LineMeter
from routeplan.analysis import reachable_after


def oracle(a, b, c):
    parent = list(range(a))
    size = [1] * a

    def root(x):
        r = x
        while parent[r] != r:
            r = parent[r]
        while parent[x] != r:
            parent[x], x = r, parent[x]
        return r

    result = [None] * len(c)
    progress = 0
    for idx in sorted(range(len(c)), key=lambda k: (c[k][2], k)):
        x, y, upto = c[idx]
        while progress < upto:
            ru, rv = root(b[progress][0]), root(b[progress][1])
            if ru != rv:
                if size[ru] < size[rv]:
                    ru, rv = rv, ru
                parent[rv] = ru
                size[ru] += size[rv]
            progress += 1
        result[idx] = root(x) == root(y)
    return result


def small_args(rng):
    count = rng.randint(1, 10)
    links = [(rng.randrange(count), rng.randrange(count)) for _ in range(rng.randint(0, 14))]
    questions = [(rng.randrange(count), rng.randrange(count), rng.randint(0, len(links))) for _ in range(rng.randint(0, 10))]
    return (count, links, questions)


def big_args(rng, n):
    links = [(rng.randrange(n), rng.randrange(n)) for _ in range(int(n * 1.3))]
    questions = [(rng.randrange(n), rng.randrange(n), rng.randint(0, len(links))) for _ in range(n)]
    return (n, links, questions)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(2003)
        for _ in range(150):
            args = small_args(rng)
            self.assertEqual(reachable_after(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_inputs_are_not_modified(self):
        rng = random.Random(2004)
        for _ in range(40):
            args = small_args(rng)
            before = copy.deepcopy(args)
            reachable_after(*args)
            self.assertEqual(args, before)

