"""routeplan: calculations used by the nightly batch jobs."""


def reachable_after(sites, bridges, probes):
    """Whether two islands were joined by the time a given number of bridges had been built."""
    parent = list(range(sites))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    order = sorted(range(len(probes)), key=lambda i: probes[i][2])
    answers = [False] * len(probes)
    added = 0
    for i in order:
        x, y, upto = probes[i]
        while added < upto:
            u, v = bridges[added]
            parent[find(u)] = find(v)
            added += 1
        answers[i] = find(x) == find(y)
    return answers


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

