"""routeplan: calculations used by the nightly batch jobs."""


def reachable_after(sites, bridges, probes):
    """Whether two islands were joined by the time a given number of bridges had been built."""
    answers = []
    for x, y, upto in probes:
        adj = {}
        for u, v in bridges[:upto]:
            adj.setdefault(u, []).append(v)
            adj.setdefault(v, []).append(u)
        seen = {x}
        stack = [x]
        while stack:
            cur = stack.pop()
            for nxt in adj.get(cur, ()):
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        answers.append(y in seen)
    return answers


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

