import heapq


def shortest_fares(links, hub):
    """Lowest fare from the hub to every airport that can be reached."""
    dist = {hub: 0}
    heap = [(0, hub)]
    while heap:
        d, node = heapq.heappop(heap)
        if d > dist[node]:
            continue
        for nbr, w in links.get(node, ()):
            nd = d + w
            if nd < dist.get(nbr, nd + 1):
                dist[nbr] = nd
                heapq.heappush(heap, (nd, nbr))
    return dist


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

