def shortest_fares(links, hub):
    """Lowest fare from the hub to every airport that can be reached."""
    dist = {hub: 0}
    done = set()
    while True:
        node = None
        for cand, d in dist.items():
            if cand not in done and (node is None or d < dist[node]):
                node = cand
        if node is None:
            break
        done.add(node)
        for nbr, w in links.get(node, ()):
            nd = dist[node] + w
            if nd < dist.get(nbr, float("inf")):
                dist[nbr] = nd
