def common_stretch(left, right):
    """How much of two versions of a line survives unchanged, as a subsequence."""
    prev = [0] * (len(right) + 1)
    for x in left:
        cur = [0]
        for j, y in enumerate(right):
            cur.append(prev[j] + 1 if x == y else max(prev[j + 1], cur[j]))
        prev = cur
    return prev[-1]


