def common_stretch(left, right):
    """How much of two versions of a line survives unchanged, as a subsequence."""

    def go(i, j):
        if i == len(left) or j == len(right):
            return 0
        if left[i] == right[j]:
            return 1 + go(i + 1, j + 1)
        return max(go(i + 1, j), go(i, j + 1))

    return go(0, 0)


