def oracle(a):
    jobs = sorted(a, key=lambda job: (job[1], job[0], job[2]))
    best = [0] * (len(jobs) + 1)
    for k, (s, e, p) in enumerate(jobs, 1):
        compatible = max((best[m] for m in range(k) if m == 0 or jobs[m - 1][1] <= s), default=0)
        best[k] = max(best[k - 1], compatible + p)
    return best[-1]


