def max_contract_income(contracts):
    """The highest total income from contracts that can be worked one after the other."""
    jobs = sorted(contracts)

    def best(i):
        if i == len(jobs):
            return 0
        s, e, p = jobs[i]
        j = i + 1
        while j < len(jobs) and jobs[j][0] < e:
            j += 1
        return max(best(i + 1), p + best(j))

    return best(0)


