import copy
import importlib
import os
import random
import unittest

from linemeter import BudgetExceeded, LineMeter
from ledgerlab.queries import cumulative_between


def oracle(a, b):
    return [sum(a[lo:hi]) for lo, hi in b]


def small_args(rng):
    values = [rng.randint(-9, 99) for _ in range(rng.randint(0, 25))]
    queries = []
    for _ in range(rng.randint(0, 12)):
        lo = rng.randint(0, len(values))
        queries.append((lo, rng.randint(lo, len(values))))
    return (values, queries)


def big_args(rng, n):
    values = [rng.randint(-50, 500) for _ in range(n)]
    queries = [(rng.randint(0, n // 4), rng.randint(3 * n // 4, n)) for _ in range(n // 2)]
    return (values, queries)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(2009)
        for _ in range(150):
            args = small_args(rng)
            self.assertEqual(cumulative_between(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_inputs_are_not_modified(self):
        rng = random.Random(2010)
        for _ in range(40):
            args = small_args(rng)
            before = copy.deepcopy(args)
            cumulative_between(*args)
            self.assertEqual(args, before)

