"""batchcalc: calculations used by the nightly batch jobs."""
import bisect


def longest_climb(heights):
    """Longest chain of measurements that keeps strictly rising when you skip the dips."""
    tails = []
    for x in heights:
        k = bisect.bisect_left(tails, x)
        if k == len(tails):
            tails.append(x)
        else:
            tails[k] = x
    return len(tails)


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

