def longest_climb(heights):
    """Longest chain of measurements that keeps strictly rising when you skip the dips."""
    best = [1] * len(heights)
    for i in range(len(heights)):
        for j in range(i):
            if heights[j] < heights[i] and best[j] + 1 > best[i]:
                best[i] = best[j] + 1
    return max(best, default=0)


