"""opsmath: calculations used by the nightly batch jobs."""


def cheapest_trip(flights, origin, target, max_legs):
    """Cheapest itinerary with a limited number of legs."""
    inf = float("inf")
    cost = {origin: 0}
    result = 0 if origin == target else inf
    for _ in range(max_legs):
        nxt_cost = dict(cost)
        for node, so_far in cost.items():
            for nxt, price in flights.get(node, ()):
                if so_far + price < nxt_cost.get(nxt, inf):
                    nxt_cost[nxt] = so_far + price
        cost = nxt_cost
        if target in cost:
            result = min(result, cost[target])
    return -1 if result == inf else result


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

