"""opsmath: calculations used by the nightly batch jobs."""


def cheapest_trip(flights, origin, target, max_legs):
    """Cheapest itinerary with a limited number of legs."""
    best = [-1]

    def walk(node, left, cost):
        if node == target and (best[0] == -1 or cost < best[0]):
            best[0] = cost
        if left == 0:
            return
        for nxt, price in flights.get(node, ()):
            walk(nxt, left - 1, cost + price)

    walk(origin, max_legs, 0)
    return best[0]


