import unittest

from linemeter import BudgetExceeded, LineMeter
from batchcalc.queries import max_overlap


def oracle(a):
    import heapq
    ends, best = [], 0
    for s, e in sorted(a):
        while ends and ends[0] <= s:
            heapq.heappop(ends)
        heapq.heappush(ends, e)
        best = max(best, len(ends))
    return best


def small_args(rng):
    items = []
    for _ in range(rng.randint(0, 12)):
        s = rng.randint(0, 30)
        items.append((s, s + rng.randint(1, 10)))
    return (items,)


def big_args(rng, n):
    items = []
    for _ in range(n):
        s = rng.randint(0, 4 * n)
        items.append((s, s + rng.randint(1, 300)))
    return (items,)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(2013)
        for _ in range(150):
            args = small_args(rng)
            self.assertEqual(max_overlap(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_inputs_are_not_modified(self):
        rng = random.Random(2014)
        for _ in range(40):
            args = small_args(rng)
            before = copy.deepcopy(args)
            max_overlap(*args)
            self.assertEqual(args, before)

