def longest_clean_run(events):
    """Longest stretch of the event log without the same event id twice."""
    last = {}
    start = best = 0
    for i, item in enumerate(events):
        if item in last and last[item] >= start:
            start = last[item] + 1
        last[item] = i
        best = max(best, i - start + 1)
    return best


