def longest_clean_run(events):
    """Longest stretch of the event log without the same event id twice."""
    best = 0
    for start in range(len(events)):
        seen = set()
        for item in events[start:]:
            if item in seen:
                break
            seen.add(item)
        best = max(best, len(seen))
    return best


