"""routeplan: calculations used by the nightly batch jobs."""
from collections import deque


def steps_to_exit(maze, begin, target):
    """Length of the shortest path through the maze."""
    dist = {begin: 0}
    queue = deque([begin])
    while queue:
        r, c = queue.popleft()
        if (r, c) == target:
            return dist[(r, c)]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(maze) and 0 <= nc < len(maze[0]) and maze[nr][nc] != "#" and (nr, nc) not in dist:
                dist[(nr, nc)] = dist[(r, c)] + 1
                queue.append((nr, nc))
    return -1


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

