"""routeplan: calculations used by the nightly batch jobs."""


def steps_to_exit(maze, begin, target):
    """Length of the shortest path through the maze."""
    best = [-1]

    def walk(r, c, steps, seen):
        if best[0] != -1 and steps >= best[0]:
            return
        if (r, c) == target:
            best[0] = steps
            return
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(maze) and 0 <= nc < len(maze[0]) and maze[nr][nc] != "#" and (nr, nc) not in seen:
                walk(nr, nc, steps + 1, seen | {(nr, nc)})

    walk(begin[0], begin[1], 0, {begin})
    return best[0]


