def can_fill_exactly(weights, capacity):
    """Whether some of the parcels fill the van exactly to its capacity."""

    def go(i, left):
        if left == 0:
            return True
        if i == len(weights) or left < 0:
            return False
        return go(i + 1, left - weights[i]) or go(i + 1, left)

    return go(0, capacity)


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

