def linked_by_then(count, cables, checks):
    """Whether two machines could talk to each other at a given point of the cabling work."""
    parent = list(range(count))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    order = sorted(range(len(checks)), key=lambda i: checks[i][2])
    answers = [False] * len(checks)
