def best_booking_value(offers):
    """Choose which booking offers to accept so that the revenue is as high as possible."""
    jobs = sorted(offers)

    def best(i):
        if i == len(jobs):
            return 0
        s, e, p = jobs[i]
        j = i + 1
        while j < len(jobs) and jobs[j][0] < e:
            j += 1
        return max(best(i + 1), p + best(j))

    return best(0)


