def steadiest_stretch(changes, goal):
    """Longest run of consecutive daily changes that adds up to the goal."""
    first = {0: -1}
    total = best = 0
    for i, v in enumerate(changes):
        total += v
        if total - goal in first:
            best = max(best, i - first[total - goal])
        first.setdefault(total, i)
    return best


