"""batchcalc: calculations used by the nightly batch jobs."""
import heapq


def route_costs(roads, origin):
    """Cheapest travel cost from the depot to every town it can reach."""
    dist = {origin: 0}
    heap = [(0, origin)]
    while heap:
        d, node = heapq.heappop(heap)
        if d > dist[node]:
            continue
        for nbr, w in roads.get(node, ()):
            nd = d + w
            if nd < dist.get(nbr, nd + 1):
                dist[nbr] = nd
                heapq.heappush(heap, (nd, nbr))
    return dist


