"""batchcalc: calculations used by the nightly batch jobs."""


def route_costs(roads, origin):
    """Cheapest travel cost from the depot to every town it can reach."""
    dist = {origin: 0}
    done = set()
    while True:
        node = None
        for cand, d in dist.items():
            if cand not in done and (node is None or d < dist[node]):
                node = cand
        if node is None:
            break
        done.add(node)
        for nbr, w in roads.get(node, ()):
            nd = dist[node] + w
            if nd < dist.get(nbr, float("inf")):
                dist[nbr] = nd
    return dist


