"""sched: calculations used by the nightly batch jobs."""
from collections import deque


def min_moves(floor, entry, exit_cell):
    """Minimum number of steps from the entrance to the exit of a floor plan."""
    dist = {entry: 0}
    queue = deque([entry])
    while queue:
        r, c = queue.popleft()
        if (r, c) == exit_cell:
            return dist[(r, c)]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(floor) and 0 <= nc < len(floor[0]) and floor[nr][nc] != "#" and (nr, nc) not in dist:
                dist[(nr, nc)] = dist[(r, c)] + 1
                queue.append((nr, nc))
    return -1


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

