"""sched: calculations used by the nightly batch jobs."""


def min_moves(floor, entry, exit_cell):
    """Minimum number of steps from the entrance to the exit of a floor plan."""
    best = [-1]

    def walk(r, c, steps, seen):
        if best[0] != -1 and steps >= best[0]:
            return
        if (r, c) == exit_cell:
            best[0] = steps
            return
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(floor) and 0 <= nc < len(floor[0]) and floor[nr][nc] != "#" and (nr, nc) not in seen:
                walk(nr, nc, steps + 1, seen | {(nr, nc)})

    walk(entry[0], entry[1], 0, {entry})
    return best[0]


